nextflow_process {

    name "Test Process RCLONE_CHECKSUM"
    script "../main.nf"
    process "RCLONE_CHECKSUM"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "rclone"
    tag "rclone/checksum"

    test("test - md5 - match") {

        when {
            process {
                """
                file('rclone.config').text = '[s3]\\ntype = s3\\nprovider = AWS\\nregion = eu-west-1\\nenv_auth = false\\nno_check_bucket = true'

                input[0] = [[id:'test'], file(params.modules_testdata_base_path + 'generic/txt/snpeff_cache_md5.txt', checkIfExists: true), 'MD5', "s3://annotation-cache/snpeff_cache/WBcel235.105/"]
                input[1] = file('rclone.config')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("test - md5 - stub") {
        options "-stub"

        when {
            process {
                """
                file('test.md5').text = 'e59ff97941044f85df5297e1c302d260  hello.txt\\n'

                input[0] = [[id:'test'], file('test.md5'), 'MD5', "s3://nf-core-test-datasets/modules/data/delete_me/malt/"]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("test - md5 - differs") {
        when {
            process {
                """
                file('test_bad.md5').text = '00000000000000000000000000000000  hello.txt'
                file('rclone.config').text = '[s3]\\ntype = s3\\nprovider = AWS\\nregion = eu-west-1\\nenv_auth = false\\nno_check_bucket = true'

                input[0] = [[id:'test'], file('test_bad.md5'), 'MD5', "s3://annotation-cache/snpeff_cache/WBcel235.105/"]
                input[1] = file('rclone.config')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

